        as.raw(c(0x84, 0xe5, 0x9e, 0x04)),
        pack("<I", flags),
        serialize_bytes(self$currency),
        .telegramR_tl_vector(self$prices),
        if (!is.null(self$max_tip_amount)) packInt64(self$max_tip_amount) else raw(0),
        if (!is.null(self$suggested_tip_amounts)) c(as.raw(c(0x15, 0xc4, 0xb5, 0x1c)), pack("<i", length(self$suggested_tip_amounts)), if (length(self$suggested_tip_amounts) > 0) do.call(c, lapply(self$suggested_tip_amounts, function(x) packInt64(x))) else raw(0)) else raw(0),
        if (!is.null(self$terms_url)) serialize_bytes(self$terms_url) else raw(0),
        if (!is.null(self$subscription_period)) pack("<i", self$subscription_period) else raw(0)
      )
    },
    serialize = function() self$bytes()
  ),
  private = list(
    from_reader = function(reader) {
      flags <- reader$read_int()
      self$test <- bitwAnd(flags, 1L) != 0
      self$name_requested <- bitwAnd(flags, 2L) != 0
      self$phone_requested <- bitwAnd(flags, 4L) != 0
      self$email_requested <- bitwAnd(flags, 8L) != 0
      self$shipping_address_requested <- bitwAnd(flags, 16L) != 0
      self$flexible <- bitwAnd(flags, 32L) != 0
      self$phone_to_provider <- bitwAnd(flags, 64L) != 0
      self$email_to_provider <- bitwAnd(flags, 128L) != 0
      self$recurring <- bitwAnd(flags, 512L) != 0
      self$currency <- reader$tgread_string()
      self$prices <- reader$tgread_vector()
      self$max_tip_amount <- if (bitwAnd(flags, 256L) != 0) reader$read_long() else NULL
      self$suggested_tip_amounts <- if (bitwAnd(flags, 256L) != 0) { reader$read_int(); n_ <- reader$read_int(); if (n_ > 0) lapply(seq_len(n_), function(.i) reader$read_long()) else list() } else NULL
      self$terms_url <- if (bitwAnd(flags, 1024L) != 0) reader$tgread_string() else NULL
      self$subscription_period <- if (bitwAnd(flags, 2048L) != 0) reader$read_int() else NULL
      self
    }
  ),
  class = TRUE,
  lock_objects = FALSE
)

