PremiumSubscriptionOption <- R6::R6Class("PremiumSubscriptionOption",
  inherit = TLObject,
  public = list(
    CONSTRUCTOR_ID = 0x5f2d1df2,
    SUBCLASS_OF_ID = 0x2e2dc73f,
    current = NULL,
    can_purchase_upgrade = NULL,
    transaction = NULL,
    months = NULL,
    currency = NULL,
    amount = NULL,
    bot_url = NULL,
    store_product = NULL,
    initialize = function(current = NULL, can_purchase_upgrade = NULL, transaction = NULL, months, currency, amount, bot_url, store_product = NULL) {
      self$current <- current
      self$can_purchase_upgrade <- can_purchase_upgrade
      self$transaction <- transaction
      self$months <- months
      self$currency <- currency
      self$amount <- amount
      self$bot_url <- bot_url
      self$store_product <- store_product
    },
    to_dict = function() {
      list(
        `_` = "PremiumSubscriptionOption",
        "current" = if (inherits(self$current, "TLObject")) self$current$to_dict() else self$current,
        "can_purchase_upgrade" = if (inherits(self$can_purchase_upgrade, "TLObject")) self$can_purchase_upgrade$to_dict() else self$can_purchase_upgrade,
        "transaction" = if (inherits(self$transaction, "TLObject")) self$transaction$to_dict() else self$transaction,
        "months" = if (inherits(self$months, "TLObject")) self$months$to_dict() else self$months,
        "currency" = if (inherits(self$currency, "TLObject")) self$currency$to_dict() else self$currency,
        "amount" = if (inherits(self$amount, "TLObject")) self$amount$to_dict() else self$amount,
        "bot_url" = if (inherits(self$bot_url, "TLObject")) self$bot_url$to_dict() else self$bot_url,
        "store_product" = if (inherits(self$store_product, "TLObject")) self$store_product$to_dict() else self$store_product
      )
    },
    to_list = function() {
      list(
        `_` = "PremiumSubscriptionOption",
        "current" = if (inherits(self$current, "TLObject")) self$current$to_dict() else self$current,
        "can_purchase_upgrade" = if (inherits(self$can_purchase_upgrade, "TLObject")) self$can_purchase_upgrade$to_dict() else self$can_purchase_upgrade,
        "transaction" = if (inherits(self$transaction, "TLObject")) self$transaction$to_dict() else self$transaction,
        "months" = if (inherits(self$months, "TLObject")) self$months$to_dict() else self$months,
        "currency" = if (inherits(self$currency, "TLObject")) self$currency$to_dict() else self$currency,
        "amount" = if (inherits(self$amount, "TLObject")) self$amount$to_dict() else self$amount,
        "bot_url" = if (inherits(self$bot_url, "TLObject")) self$bot_url$to_dict() else self$bot_url,
        "store_product" = if (inherits(self$store_product, "TLObject")) self$store_product$to_dict() else self$store_product
      )
    },
    bytes = function() {
      flags <- 0L
      if (isTRUE(self$current)) flags <- bitwOr(flags, 2L)
      if (isTRUE(self$can_purchase_upgrade)) flags <- bitwOr(flags, 4L)
      if (!is.null(self$transaction)) flags <- bitwOr(flags, 8L)
      if (!is.null(self$store_product)) flags <- bitwOr(flags, 1L)
      c(
        as.raw(c(0xf2, 0x1d, 0x2d, 0x5f)),
        pack("<I", flags),
        if (!is.null(self$transaction)) serialize_bytes(self$transaction) else raw(0),
        pack("<i", self$months),
        serialize_bytes(self$currency),
        packInt64(self$amount),
        serialize_bytes(self$bot_url),
        if (!is.null(self$store_product)) serialize_bytes(self$store_product) else raw(0)
      )
    },
    serialize = function() self$bytes()
  ),
  private = list(
    from_reader = function(reader) {
      flags <- reader$read_int()
      self$current <- bitwAnd(flags, 2L) != 0
      self$can_purchase_upgrade <- bitwAnd(flags, 4L) != 0
      self$transaction <- if (bitwAnd(flags, 8L) != 0) reader$tgread_string() else NULL
      self$months <- reader$read_int()
      self$currency <- reader$tgread_string()
      self$amount <- reader$read_long()
      self$bot_url <- reader$tgread_string()
      self$store_product <- if (bitwAnd(flags, 1L) != 0) reader$tgread_string() else NULL
      self
    }
  ),
  class = TRUE,
  lock_objects = FALSE
)

